//////
// june elva, 2025 january 31
//////
// this shader shows ways to create interesting stability inside the
// "bulbs" of a julia fractal, albeit one rendered at an artistic angle.
// though they are not always visible as time continues in this shader,
// i find their smoothness and movement, especially at low iterations,
// interesting and useful for something. useful for what, er, depends.
//
// around 25 seconds in, you can see the beginning of a "rift" or "void"
// appearing like a stretched fabric, undulating before being filled
// with the self-similarities of the more "solid" outer regions.
//
// i have positioned the time window so that the startup shows several
// interesting forms, or at least interesting to my eyes.
//
// what I see at the beginning is the void alternating between binary
// states until it is pulled thin by time, blurring into a fluid/fabric.
// also, there is some behavior to low iterations causing what otherwise
// might appear to be "solid spirals" become fabric-like themselves.
//
// inspiration from https://www.shadertoy.com/view/Ndcczj - thx!
//

// OPTION: here you can clusmily position yourself
// in the timeline if you find an area you like.
////
#define TIME_SCALE 0.03
#define TIME_OFFSET -4.9

//
// OPTION: the iterations animate up to this value
////
#define ITER_MAX 128

//
// OPTION: extra-detail version can be toggled on.
// this makes the edges of "splitting" of binary states in
// the void more apparent as they transition under tension.
// (at least near the beginning point)
// --- WARNING: in this mode there may be undesirable flicker.
////
//#define EXTRA

// this is a rather simple thing
// but here my "epsilon" is rather large
// this is to exaggerate the lighting and
// bring out the detail of the chaos zones
vec3 normalMap(vec2 uv) {
    float e = 0.5;
    float h1 = length(uv);
    float h2 = length(uv + vec2(e, 0.0));
    float h3 = length(uv + vec2(0.0, e));

    vec3 normal = vec3(h1 - h2, h1 - h3, e);
    //normal = normalize(normal);

    return normal * 0.5 + 0.5;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float time = iTime * TIME_SCALE + TIME_OFFSET;
    vec2 uv = ((2.0 * fragCoord - iResolution.xy) / iResolution.y) * (abs(sin(time)) + 0.5);

    for (int i = 0; i < ITER_MAX - int(0.5 + sin(fract(time * 0.25)) * float(ITER_MAX)); ++i) {
        uv = vec2(uv.x * uv.x - uv.y * uv.y, uv.x * uv.y) - vec2(sin(time), cos(time));
        if (dot(uv.yx * time, uv * time) > 128.0) break;
    }

#ifdef EXTRA
    float lightf = 0.5 * fract(sin(time * 4.0));
    float lightx = uv.x * lightf * sin(time * lightf);
    float lighty = uv.y * lightf * cos(time * lightf);
    float lightz = fract(sin(time * lightx / lightf));
#else
    float lightf = 32.0;
    float lightx = uv.x * lightf * sin(time * lightf);
    float lighty = uv.y * lightf * cos(time * lightf);
    float lightz = 2.0 * lightf;
#endif 

    vec3 lightDir = normalize(vec3(lightx, lighty, lightz));
    vec3 normal = normalMap(normalize(uv));
    float spec = pow(max(dot(normal, lightDir), 0.05), 0.6);

    // i balance the final color to prevent high-contrast flashing.
    fragColor = vec4(spec * mix(vec3(0.1, 0.6, 2.0), vec3(0.8, 0.0, 0.6), spec), 1.0);
}

